body.script:
(function () {
                            try {
                                var r = document.referrer, back = document.getElementById('tse-back');
                                // a participant has no panel: «کارهای من» by default, the panel only on panel addresses (W54)
                                if (location.pathname.indexOf('/my/workspaces') === 0) {
                                    back.href = '/my/workspaces';
                                    back.textContent = 'بازگشت به پنل';
                                }
                                if (r && r.indexOf(location.origin + '/') === 0 && r !== location.href) {
                                    back.href = r;
                                    back.textContent = 'بازگشت به صفحهٔ قبل';
                                }
                                var ref = document.getElementById('tse-ref');
                                var when = new Intl.DateTimeFormat('fa-IR-u-ca-persian', {dateStyle: 'medium', timeStyle: 'short'}).format(new Date());
                                ref.textContent = 'زمان خطا: ' + when;
                                ref.hidden = false;
                            } catch (e) { /* the links keep their defaults */ }
                        })();
